//! The one path every corpus a session loads is generated by.
//!
//! A corpus is authored in one directory and generated into another, and the
//! steps between are the same for every kind: walk the authored directory in name
//! order, read each source, render its templates through a fresh environment,
//! write each generated file ending in one newline, and name what sits in the
//! generated place that no source claims. A kind says only how its sources sit and
//! how one is read; everything else is here, once.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::{fs, io};

use mockspace_template::template::TemplateEnv;
use serde::Serialize;

/// Suffix of an authored template.
pub const TMPL_SUFFIX: &str = ".md.tmpl";

/// How a kind's sources sit in its authored directory, and so how its generated
/// forms sit in theirs. A fixed vocabulary: a source is a file or a directory.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shape {
    /// One `<name>.md.tmpl` per source, generated as `<name>.md`. Any other file
    /// beside them is not a source.
    File,
    /// One `<name>/` per source, generated as a directory of the same name.
    Dir,
}

/// A kind of authored source.
pub trait Kind {
    /// How its sources sit.
    const SHAPE: Shape;
    /// One source, as read.
    type Item;
    /// Why a source or the directory could not be read.
    type Error;

    /// The error for a directory or a file that could not be read.
    fn unreadable(path: PathBuf, cause: io::Error) -> Self::Error;

    /// Read the source called `name` at `path`.
    fn read(&self, name: &str, path: &Path) -> Result<Self::Item, Self::Error>;
}

/// The sources of a shape under `dir`, by name, in name order.
fn sources(dir: &Path, shape: Shape) -> io::Result<BTreeMap<String, PathBuf>> {
    let mut out = BTreeMap::new();
    for entry in fs::read_dir(dir)? {
        let path = entry?.path();
        let Some(file) = path.file_name().and_then(|f| f.to_str()) else {
            continue;
        };
        let name = match shape {
            Shape::File => file.strip_suffix(TMPL_SUFFIX).map(str::to_string),
            Shape::Dir => path.is_dir().then(|| file.to_string()),
        };
        if let Some(name) = name {
            out.insert(name, path);
        }
    }
    Ok(out)
}

/// Read every source of `K` under `dir`, in name order, refusing on the first
/// that does not read: a corpus that skipped what it could not parse would
/// report itself smaller and healthier than the one on disk.
pub fn load<K: Kind>(kind: &K, dir: &Path) -> Result<Vec<K::Item>, K::Error> {
    let found = sources(dir, K::SHAPE).map_err(|cause| K::unreadable(dir.to_path_buf(), cause))?;
    found
        .iter()
        .map(|(name, path)| kind.read(name, path))
        .collect()
}

/// Read a source file whole.
pub fn read_text<K: Kind>(path: &Path) -> Result<String, K::Error> {
    fs::read_to_string(path).map_err(|cause| K::unreadable(path.to_path_buf(), cause))
}

/// Render one template against `ctx`.
///
/// A fresh environment per render rather than one shared: strict undefined
/// handling is the point, and a shared registry would let a template resolve a
/// name some other source happened to define.
pub fn render(source: &str, ctx: &impl Serialize) -> Result<String, String> {
    TemplateEnv::new()
        .render_str(source, ctx)
        .map_err(|e| e.to_string())
}

/// Write a generated file, ending in exactly one newline: a file without one
/// concatenates with whatever is loaded after it.
pub fn write(path: &Path, text: &str) -> io::Result<()> {
    fs::write(path, format!("{}\n", text.trim_end()))
}

/// What sits in `dst` in the generated form of `shape` and is not `claimed`,
/// sorted.
///
/// Reported rather than removed: one is either a source not moved to the
/// authored side yet or something else entirely, and on disk a file the pass
/// wrote last time and one somebody put there on purpose are the same.
pub fn unclaimed(
    dst: &Path,
    shape: Shape,
    claimed: impl Fn(&str) -> bool,
) -> io::Result<Vec<String>> {
    if !dst.is_dir() {
        return Ok(Vec::new());
    }
    let mut stray = Vec::new();
    for entry in fs::read_dir(dst)? {
        let path = entry?.path();
        let name = match shape {
            Shape::File => {
                if path.extension().and_then(|e| e.to_str()) != Some("md") {
                    continue;
                }
                path.file_stem().and_then(|f| f.to_str())
            },
            Shape::Dir => {
                if !path.is_dir() {
                    continue;
                }
                path.file_name().and_then(|f| f.to_str())
            },
        };
        match name {
            Some(name) if !claimed(name) => stray.push(name.to_string()),
            _ => {},
        }
    }
    stray.sort();
    Ok(stray)
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Names;

    impl Kind for Names {
        type Error = String;
        type Item = String;

        const SHAPE: Shape = Shape::File;

        fn unreadable(path: PathBuf, cause: io::Error) -> String {
            format!("{}: {cause}", path.display())
        }

        fn read(&self, name: &str, _: &Path) -> Result<String, String> {
            Ok(name.to_string())
        }
    }

    #[test]
    fn a_file_kind_reads_only_templates_in_name_order() {
        let d = tempfile::tempdir().unwrap();
        for f in ["b.md.tmpl", "a.md.tmpl", "defaults.toml", "c.md"] {
            fs::write(d.path().join(f), "").unwrap();
        }
        assert_eq!(load(&Names, d.path()).unwrap(), ["a", "b"]);
    }

    #[test]
    fn a_missing_directory_is_unreadable_by_its_path() {
        let err = load(&Names, Path::new("/nonexistent-surface-dir")).unwrap_err();
        assert!(err.starts_with("/nonexistent-surface-dir"), "{err}");
    }

    #[test]
    fn unclaimed_names_what_no_source_claims_in_either_shape() {
        let d = tempfile::tempdir().unwrap();
        fs::write(d.path().join("kept.md"), "").unwrap();
        fs::write(d.path().join("stray.md"), "").unwrap();
        fs::create_dir(d.path().join("stray-dir")).unwrap();
        assert_eq!(
            unclaimed(d.path(), Shape::File, |n| n == "kept").unwrap(),
            ["stray"]
        );
        assert_eq!(unclaimed(d.path(), Shape::Dir, |_| false).unwrap(), [
            "stray-dir"
        ]);
    }

    #[test]
    fn write_ends_a_file_in_one_newline() {
        let d = tempfile::tempdir().unwrap();
        let p = d.path().join("x.md");
        write(&p, "text\n\n\n").unwrap();
        assert_eq!(fs::read_to_string(&p).unwrap(), "text\n");
    }
}
